import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`pinterest-seo-rewrite`,heroTitle:`Optimize your Pinterest SEO in minutes`,heroSubtitle:`Perplexity Computer scrapes your pin titles, descriptions, and board names, cross-references them against trending Pinterest search terms and top-performing competitor pins in your niche, then delivers rewritten titles and keyword-rich descriptions for your top 20 pins plus optimized board names - so your content actually shows up in Pinterest search instead of getting buried.`,inputUrlCta:`Build my plan`,inputUrlPlaceholder:`yourwebsite.com`,inputUrlPrefill:`Use {url} as the starting context for this workflow. Computer scrapes your pin titles, descriptions, and board names, cross-references them against trending Pinterest search terms and top-performing competitor pins in your niche, then delivers rewritten titles and keyword-rich descriptions for your top 20 pins plus optimized board names - so your content actually shows up in Pinterest search instead of getting buried.`,heroOverlaySteps:[`Analyzing the market, communities, keywords, or partner landscape`,`Benchmarking the strongest competitors or adjacent opportunities`,`Ranking the moves with the clearest upside`,`Action plan, shortlist, and next steps ready to use`],generatingSteps:[`Reading {url} to understand the goal, context, and market starting point`,`Designing an agent to discover high-signal opportunities and benchmark strong examples`,`Configuring ranking logic for fit, effort, and likely impact`,`Packaging the output into a shortlist with clear next-step recommendations`],featureSectionTitle:`From scattered signals to a ranked plan`,featureCardTitles:[`Connects to your research workflow`,`Outputs you can act on immediately`],featureCardDescriptions:[`Computer splits the work into discovery, benchmarking, prioritization, and packaging so the final output is grounded instead of generic.`,`Docs, Sheets, Notion, CRM notes, and planning tools can stay connected so research does not get stranded in a one-off chat.`,`Ranked opportunities. Competitor context. Draft actions. Clear next steps. Computer gives your team a plan to execute instead of raw findings.`],capabilitySectionTitle:`Your growth researcher, on demand`,capabilitySectionSubtitle:`Paste the starting context, step away, and come back to a ranked opportunity plan.`,capabilityCards:[{title:`Opportunity Discovery`,description:`Computer can map the strongest communities, keywords, partners, or accounts related to your goal and rank them by likely upside.`},{title:`Benchmarking`,description:`Computer can compare the strongest examples or competitors so you see what is already working before you choose a direction.`},{title:`Draft Recommendations`,description:`Computer can package the findings into draft responses, outreach, or action plans your team can actually use next.`},{title:`Connect Your Tools`,description:`Computer can organize the work across Docs, Sheets, Notion, and other workflow tools so research handoff takes minutes instead of hours.`},{title:`Priority Ranking`,description:`Computer can sort the best opportunities by fit, effort, and expected impact so your team knows where to start first.`},{title:`Refresh the Workflow`,description:`Computer can revisit the landscape later and update the shortlist as conditions, rankings, or conversations change.`}]});export{t as default};
